insert into public.livro_itens(ref, sistema, fonte, grupo, subgrupo, nome, ordem, dados) values
('sah:item:arma:Pregador pneumático','op','sah','arma','simples · disparo, uma mão','Pregador pneumático',1000,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 0, "esp": 1, "mc": "disparo", "desc": "Arma simples, disparo, uma mão. Ferramenta que dispara pregos sob pressão. Para os poderes que afetam armas de fogo, conta como arma de fogo. O rolo tem 300 pregos: dura a missão inteira.", "arma": {"dano": "1d4", "crit": "x4", "alc": "Curto", "td": "P", "per": "Pontaria"}}'::jsonb),
('sah:item:arma:Estilingue','op','sah','arma','simples · disparo, duas mãos','Estilingue',1001,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 0, "esp": 1, "mc": "disparo", "desc": "Arma simples, disparo, duas mãos. Ao contrário de outras armas de disparo, soma a sua Força ao dano. Dispara bolinhas reaproveitáveis (ou pedrinhas, se faltarem). Também lança granadas: com ele a granada é arremessada em alcance longo. Um pacote de bolinhas dura a missão inteira.", "arma": {"dano": "1d4", "crit": "x2", "alc": "Curto", "td": "I", "per": "Pontaria"}}'::jsonb),
('sah:item:arma:Revólver compacto','op','sah','arma','simples · fogo, leve','Revólver compacto',1002,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 1, "esp": 1, "mc": "fogo", "desc": "Arma simples, fogo, leve. Calibre baixo, feito para ser escondido. Se você for treinado em Crime, carrega uma sem que ela ocupe espaço. Usa balas curtas. Com a contagem de munição: 5 balas.", "arma": {"dano": "2d4", "crit": "19/x3", "alc": "Curto", "td": "P", "per": "Pontaria"}}'::jsonb),
('sah:item:arma:Baioneta','op','sah','arma','tática · corpo a corpo, leve','Baioneta',1003,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 0, "esp": 1, "mc": "corpo", "desc": "Arma tática, corpo a corpo, leve. Lâmina para fixar em fuzil ou arma parecida. Fixar numa arma de fogo de duas mãos gasta ação de movimento; fixada, a baioneta vira arma de duas mãos ágil e seu dano sobe para 1d6. Você ainda ataca à distância com a arma de fogo, mas com –1d20 nesses ataques.", "arma": {"dano": "1d4", "crit": "19", "alc": "", "td": "P", "per": "Luta"}}'::jsonb),
('sah:item:arma:Faca tática','op','sah','arma','tática · corpo a corpo, leve','Faca tática',1004,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 1, "esp": 1, "mc": "corpo", "desc": "Arma tática, corpo a corpo, leve. Arma ágil: usa Agilidade em vez de Força no ataque e no dano. Pode ser arremessada. Na ação especial contra-ataque, dá +2 no teste de ataque. Na ação especial bloqueio, gaste 2 PE e sacrifique a faca para aumentar a RD do bloqueio em +20.", "arma": {"dano": "1d6", "crit": "19", "alc": "Curto", "td": "C", "per": "Luta"}}'::jsonb),
('sah:item:arma:Gancho de carne','op','sah','arma','tática · corpo a corpo, leve','Gancho de carne',1005,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 0, "esp": 1, "mc": "corpo", "desc": "Arma tática, corpo a corpo, leve. Gancho de frigorífico usado como arma. Amarrado a corda ou corrente, o alcance sobe para 4,5m e o item passa a ocupar 2 espaços.", "arma": {"dano": "1d4", "crit": "x4", "alc": "", "td": "P", "per": "Luta"}}'::jsonb),
('sah:item:arma:Bastão policial','op','sah','arma','tática · corpo a corpo, uma mão','Bastão policial',1006,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 1, "esp": 1, "mc": "corpo", "desc": "Arma tática, corpo a corpo, uma mão. Arma ágil: usa Agilidade em vez de Força no ataque e no dano. Serve para aparar: na ação especial esquiva, o bônus na Defesa aumenta em +1.", "arma": {"dano": "1d6", "crit": "x2", "alc": "Curto", "td": "I", "per": "Luta"}}'::jsonb),
('sah:item:arma:Picareta','op','sah','arma','tática · corpo a corpo, uma mão','Picareta',1007,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 0, "esp": 1, "mc": "corpo", "desc": "Arma tática, corpo a corpo, uma mão. Ferramenta de mineração e demolição usada como arma na falta de algo melhor.", "arma": {"dano": "1d6", "crit": "x4", "alc": "", "td": "P", "per": "Luta"}}'::jsonb),
('sah:item:arma:Shuriken','op','sah','arma','tática · arremesso','Shuriken',1008,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 1, "esp": 0.5, "mc": "arremesso", "desc": "Arma tática, arremesso. Arma de arremesso (soma Força ao dano). Se você for veterano em Pontaria, uma vez por rodada, ao atacar com shuriken, pode gastar 1 PE para fazer um ataque adicional de shuriken contra o mesmo alvo. Uma shuriken representa um pacote para duas cenas (10 shurikens, com a contagem de munição).", "arma": {"dano": "1d4", "crit": "x2", "alc": "Curto", "td": "P", "per": "Pontaria"}}'::jsonb),
('sah:item:arma:Pistola pesada','op','sah','arma','tática · fogo, uma mão','Pistola pesada',1009,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 1, "esp": 1, "mc": "fogo", "desc": "Arma tática, fogo, uma mão. Calibre maior que o da pistola. Potência e recuo dão –1d20 no ataque; empunhá-la com as duas mãos anula a penalidade. Usa balas curtas. Com a contagem de munição: 10 balas.", "arma": {"dano": "2d8", "crit": "18", "alc": "Curto", "td": "B", "per": "Pontaria"}}'::jsonb),
('sah:item:arma:Espingarda de cano duplo','op','sah','arma','tática · fogo, duas mãos','Espingarda de cano duplo',1010,'{"comp": "sah", "pag": 37, "tipo": "arma", "catg": 2, "esp": 2, "mc": "fogo", "desc": "Arma tática, fogo, duas mãos. Dois canos, cada um com um gatilho e um cartucho. Depois de disparar os dois, recarregar gasta ação de movimento. Pode disparar os dois canos no mesmo alvo: –1d20 no ataque, mas o dano sobe para 6d6. Usa cartuchos. Com a contagem de munição: 2 balas.", "arma": {"dano": "4d6", "crit": "x3", "alc": "Curto", "td": "B", "per": "Pontaria"}}'::jsonb),
('sah:item:municao:Bolinhas de estilingue','op','sah','municao','munição','Bolinhas de estilingue',1011,'{"comp": "sah", "pag": 37, "tipo": "municao", "catg": 0, "esp": 1, "desc": "Pacote de bolinhas (ou pedrinhas) para estilingue. Reaproveitáveis: o pacote dura a missão inteira. Ocupa o mesmo espaço do estilingue.", "fx": [["Serve em", "Estilingue"], ["Dura", "A missão inteira"]]}'::jsonb),
('sah:item:modificacao:Carregador Rápido','op','sah','modificacao','modificação','Carregador Rápido',1012,'{"comp": "sah", "pag": 38, "tipo": "modificacao", "aplica": ["fogo", "disparo"], "desc": "Só para quem usa a regra opcional de contagem de munição (OPRPG p.174). Para armas de fogo, bestas e balestras. Em arma de fogo, recarrega como ação livre, uma vez por rodada. Em besta ou balestra, permite até cinco recargas como ação livre, com apenas uma mão; depois disso é preciso recarregar o carregador, um virote por vez (ação de movimento por virote).", "mod": {"catg": 1, "esp": 0, "def": 0}, "fx": [["Efeito", "Recarrega como ação livre"], ["Só vale", "Armas de fogo, bestas e balestras"], ["Regra opcional", "Contagem de munição"]]}'::jsonb),
('sah:item:modificacao:Bateria Potente','op','sah','modificacao','modificação','Bateria Potente',1013,'{"comp": "sah", "pag": 39, "tipo": "modificacao", "aplica": ["acessorio"], "desc": "Para objetos elétricos. Em lanternas, celulares e notebooks, dobra a duração da bateria e o alcance da luz. Em taser, dobra os usos, aumenta o dano para 1d8 e a DT para resistir em +5. Em outros objetos, conforme a proposta do jogador e a critério do mestre.", "mod": {"catg": 1, "esp": 0, "def": 0}, "fx": [["Luz", "Alcance dobrado (lanterna, celular, notebook)"], ["Taser", "Usos dobrados, dano 1d8, DT +5"], ["Bateria", "Dura o dobro"]]}'::jsonb),
('sah:item:modificacao:Lente de Revelação','op','sah','modificacao','modificação paranormal','Lente de Revelação',1014,'{"comp": "sah", "pag": 45, "tipo": "modificacao", "aplica": ["camera"], "elemento": "Conhecimento", "desc": "Modificação paranormal para câmeras de aura paranormal. A câmera com a lente vê seres invisíveis e incorpóreos e ignora a camuflagem deles. Além disso, ação padrão e 1 PE para fotografar uma criatura em alcance curto: até o fim da cena ela perde camuflagem e invisibilidade e se torna corpórea (Vontade DT Pre evita). O livro não dá a categoria da lente; pela Câmera Obscura (categoria III com a lente, contra II da câmera comum), ela sobe a categoria em I.", "mod": {"catg": 1, "esp": 0, "def": 0}, "fx": [["Efeito", "Vê invisíveis e incorpóreos, ignora camuflagem"], ["Fotografar", "Ação padrão e 1 PE, alcance curto"], ["Teste", "Vontade DT Pre evita"], ["Só vale", "Câmera de aura paranormal"]]}'::jsonb),
('sah:item:acessorio:Amuleto Sagrado','op','sah','acessorio','acessório','Amuleto Sagrado',1015,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 0, "esp": 1, "mc": "acessorio", "desc": "Xale, rosário, fio de contas ou outro objeto que reforça a sua fé. Ocupa o espaço de um item vestido e dá +2 em Religião e Vontade.", "fx": [["Bônus", "+2 em Religião e Vontade"], ["Uso", "Vestido"]], "ef": [{"a": "per:Religião", "v": 2}, {"a": "per:Vontade", "v": 2}], "precisaEq": true}'::jsonb),
('sah:item:acessorio:Celular','op','sah','acessorio','acessório','Celular',1016,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 0, "esp": 1, "mc": "acessorio", "desc": "Tira fotos, grava áudio e vídeo, acessa a internet e liga para outras pessoas. Com acesso à internet, dá +2 em testes de perícia que envolvem adquirir informações. A lanterna é fraca, mas serve na falta de coisa melhor: ilumina um cone de 4,5m.", "fx": [["Bônus", "+2 em testes para adquirir informações (com internet)"], ["Luz", "Cone de 4,5m"]], "luz": {"t": "c", "m": 4.5}}'::jsonb),
('sah:item:acessorio:Chave de Fenda Universal','op','sah','acessorio','acessório','Chave de Fenda Universal',1017,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 0, "esp": 1, "mc": "acessorio", "desc": "Resolve quase qualquer problema: +2 em testes de perícia para criar ou reparar objetos, de panelas a motores de avião. Também dá o bônus como item de apoio em situações especiais, como mexer em cabos para hackear um servidor.", "fx": [["Bônus", "+2 em testes para criar ou reparar objetos"]]}'::jsonb),
('sah:item:acessorio:Chaves','op','sah','acessorio','acessório','Chaves',1018,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 0, "esp": 1, "mc": "acessorio", "desc": "Molho de chaves (casa, veículo, cadeados). Usar o barulho do molho para distrair alguém (jogando as chaves, por exemplo) dá +2 em testes de Furtividade feitos na mesma rodada.", "fx": [["Bônus", "+2 em Furtividade na rodada em que distrai com o barulho"]]}'::jsonb),
('sah:item:acessorio:Documentos Falsos','op','sah','acessorio','acessório','Documentos Falsos',1019,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 1, "esp": 1, "mc": "acessorio", "desc": "Identidade funcional, carteira de habilitação, cartões de crédito etc. em nome de uma identidade falsa. +2 em testes de Diplomacia, Enganação e Intimidação para se passar pela pessoa dos documentos.", "fx": [["Bônus", "+2 em Diplomacia, Enganação e Intimidação para se passar pela identidade"]]}'::jsonb),
('sah:item:acessorio:Manual Operacional','op','sah','acessorio','acessório','Manual Operacional',1020,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 1, "esp": 1, "mc": "acessorio", "desc": "Livro de lições práticas sobre um assunto: existe um manual para cada perícia. Gastar uma ação de interlúdio lendo permite usar essa perícia como se fosse treinado até o próximo interlúdio. Um manual aprimorado (OPRPG p.64) também dá +5 na perícia. Só vale o benefício de um manual por vez.", "fx": [["Efeito", "Usa a perícia como treinado até o próximo interlúdio"], ["Ler", "Ação de interlúdio"], ["Limite", "Um manual por vez"]]}'::jsonb),
('sah:item:acessorio:Notebook','op','sah','acessorio','acessório','Notebook',1021,'{"comp": "sah", "pag": 39, "tipo": "geral", "catg": 0, "esp": 2, "mc": "acessorio", "desc": "Como o celular: com internet, dá +2 em testes de perícia que envolvem adquirir informações. A tela maior serve melhor para entretenimento: ao relaxar em interlúdio, você recupera 1 ponto adicional de Sanidade. A luz do monitor ilumina um cone de 4,5m. Tablets contam como notebook.", "fx": [["Bônus", "+2 em testes para adquirir informações (com internet)"], ["Relaxar", "+1 Sanidade no interlúdio"], ["Luz", "Cone de 4,5m"]], "luz": {"t": "c", "m": 4.5}}'::jsonb),
('sah:item:explosivo:Dinamite','op','sah','explosivo','explosivo','Dinamite',1022,'{"comp": "sah", "pag": 41, "tipo": "consumivel", "catg": 1, "esp": 1, "desc": "Bastão de nitroglicerina de 20 cm. Com a mesma ação padrão você acende o pavio com uma mão e arremessa com a outra em um ponto em alcance médio. Atinge raio de 6m: seres e objetos soltos sofrem 4d6 de impacto e 4d6 de fogo e ficam em chamas (Reflexos DT Agi reduz à metade e evita as chamas).", "fx": [["Dano", "4d6 impacto + 4d6 fogo + em chamas"], ["Uso", "Acender e arremessar (ação padrão)"], ["Alcance", "Médio"], ["Área", "Raio de 6m"], ["Teste", "Reflexos DT Agi: metade e evita as chamas"]]}'::jsonb),
('sah:item:explosivo:Explosivo Plástico','op','sah','explosivo','explosivo','Explosivo Plástico',1023,'{"comp": "sah", "pag": 41, "tipo": "consumivel", "catg": 1, "esp": 1, "desc": "Massa adesiva do tamanho de uma esponja, com pinos de ignição e detonador remoto. Preparar os pinos e grudar numa superfície leva duas rodadas. Detona com o detonador (ação livre, até alcance longo) ou se sofrer ao menos 1 ponto de dano de fogo ou eletricidade. Causa 16d6 de impacto em todos os seres e objetos num raio de 3m (Reflexos DT Int reduz à metade). Um especialista em explosivos (treinado em Crime ou em uma Profissão adequada, a critério do mestre) causa o dobro de dano em objetos e estruturas e ignora a RD deles.", "fx": [["Dano", "16d6 impacto"], ["Área", "Raio de 3m"], ["Teste", "Reflexos DT Int: metade"], ["Preparar", "Duas rodadas"], ["Detonar", "Ação livre, até alcance longo"], ["Especialista", "Dobro de dano em objetos e ignora RD"]]}'::jsonb),
('sah:item:explosivo:Galão Vermelho','op','sah','explosivo','explosivo','Galão Vermelho',1024,'{"comp": "sah", "pag": 41, "tipo": "consumivel", "catg": 0, "esp": 2, "desc": "Galão vermelho ou marcado com símbolo de chama: guarda substância inflamável. Ao sofrer dano de fogo ou balístico, explode numa esfera de 6m de raio: 12d6 de fogo e em chamas (Reflexos DT 25 reduz à metade e evita as chamas). A área fica em chamas (1d6 de fogo por rodada em seres e objetos) até ser apagada ou a cena acabar (OPRPG p.292, Fogo e Fumaça).", "fx": [["Dano", "12d6 fogo + em chamas"], ["Dispara", "Ao sofrer dano de fogo ou balístico"], ["Área", "Esfera de 6m de raio"], ["Teste", "Reflexos DT 25: metade e evita as chamas"], ["Depois", "Área em chamas, 1d6 de fogo por rodada"]]}'::jsonb),
('sah:item:explosivo:Granada de Gás Sonífero','op','sah','explosivo','explosivo','Granada de Gás Sonífero',1025,'{"comp": "sah", "pag": 41, "tipo": "consumivel", "catg": 1, "esp": 1, "desc": "Libera fumaça branca num raio de 6m do ponto de impacto, por 2 rodadas. Quem começa o turno na área fica inconsciente e caído; se estiver em atividade física intensa (como combate), fica exausto por 1 rodada e depois fatigado. Em ambos os casos, Fortitude DT Agi reduz para fatigado por 1d4 rodadas.", "fx": [["Efeito", "Inconsciente (ou exausto 1 rodada, depois fatigado)"], ["Área", "Raio de 6m"], ["Duração", "2 rodadas"], ["Teste", "Fortitude DT Agi: só fatigado por 1d4 rodadas"]]}'::jsonb),
('sah:item:explosivo:Granada de PEM','op','sah','explosivo','explosivo','Granada de PEM',1026,'{"comp": "sah", "pag": 41, "tipo": "consumivel", "catg": 1, "esp": 1, "desc": "Emite um pulso eletromagnético que desativa todos os equipamentos elétricos num raio de 18m até o fim da cena. Criaturas de Energia na área sofrem 6d6 de impacto e ficam paralisadas por 1 rodada (uma vez por cena; Fortitude DT Agi reduz à metade e evita a condição).", "fx": [["Efeito", "Desativa equipamentos elétricos até o fim da cena"], ["Área", "Raio de 18m"], ["Dano", "6d6 impacto em criaturas de Energia + paralisadas 1 rodada"], ["Teste", "Fortitude DT Agi: metade e evita a paralisia"]]}'::jsonb),
('sah:item:operacional:Alarme de Movimento','op','sah','operacional','item operacional','Alarme de Movimento',1027,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 0, "esp": 1, "desc": "Objeto pequeno controlado por dispositivo móvel ou aplicativo de celular. Ação completa para posicionar e ativar. Depois, sempre que houver movimento significativo num cone de 30m para onde foi apontado, sinaliza o dispositivo de controle. Dá para regular a sensibilidade (padrão: ser Pequeno ou maior em movimento). A sinalização pode ser discreta (só no dispositivo) ou um alarme sonoro alto.", "fx": [["Efeito", "Avisa movimento na área"], ["Ativar", "Ação completa"], ["Área", "Cone de 30m"], ["Aviso", "Discreto ou sonoro"]]}'::jsonb),
('sah:item:operacional:Alimento Energético','op','sah','operacional','item operacional','Alimento Energético',1028,'{"comp": "sah", "pag": 42, "tipo": "consumivel", "catg": 2, "esp": 1, "desc": "Alimentos e suplementos de alta tecnologia que recuperam a energia mental. Ação padrão para consumir.", "fx": [["Cura", "1d4 PE"], ["Uso", "Ação padrão"]]}'::jsonb),
('sah:item:operacional:Aplicador de Medicamentos','op','sah','operacional','item operacional','Aplicador de Medicamentos',1029,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 1, "esp": 1, "desc": "Bomba injetora portátil, presa ao braço ou à perna, que aplica uma substância (cicatrizante, medicamento) com uma ação de movimento. Tem espaço para três doses (já contado no espaço do item). Carregar uma dose é ação padrão.", "fx": [["Efeito", "Aplica a substância como ação de movimento"], ["Doses", "3"], ["Carregar", "Ação padrão por dose"]]}'::jsonb),
('sah:item:operacional:Braçadeira Reforçada','op','sah','operacional','item operacional','Braçadeira Reforçada',1030,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 1, "esp": 1, "desc": "Proteção de artes marciais e esportes de contato que ajuda a absorver o impacto ao bloquear com o braço. Aumenta em +2 a RD que você recebe ao bloquear.", "fx": [["Efeito", "+2 na RD do bloqueio"]]}'::jsonb),
('sah:item:operacional:Cão Adestrado','op','sah','operacional','item operacional','Cão Adestrado',1031,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 1, "esp": 0, "desc": "Cão grande e corajoso (pastor alemão, dobermann, fila brasileiro, caramelo) treinado para ajudar em investigação e combate. Personagem treinado em Adestramento pode usá-lo como aliado (OPRPG p.171). Bônus: +2 em Investigação e Percepção. Ladrar e Morder: gaste 1 PE para o cão assumir postura defensiva ao seu redor; você recebe +2 na Defesa por 1 rodada.", "fx": [["Tipo", "Aliado (precisa de Adestramento)"], ["Bônus", "+2 em Investigação e Percepção"], ["Ladrar e Morder", "1 PE: +2 Defesa por 1 rodada"], ["Espaço", "Não ocupa"]], "ef": [{"a": "per:Investigação", "v": 2}, {"a": "per:Percepção", "v": 2}], "aliado": true}'::jsonb),
('sah:item:operacional:Coldre Saque Rápido','op','sah','operacional','item operacional','Coldre Saque Rápido',1032,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 1, "esp": 1, "desc": "Coldre que permite sacar ou guardar a arma com movimento mínimo. Uma vez por rodada, saca ou guarda uma arma de fogo leve como ação livre.", "fx": [["Efeito", "Saca ou guarda arma de fogo leve como ação livre"], ["Limite", "1 vez por rodada"]]}'::jsonb),
('sah:item:operacional:Equipamento de Escuta','op','sah','operacional','item operacional','Equipamento de Escuta',1033,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 1, "esp": 1, "desc": "Um receptor com alcance de 90m e três transmissores minúsculos que captam sons num raio de 9m. Instalar um transmissor leva alguns minutos e exige Crime contra DT 20 (falha: a escuta não transmite). O resultado do teste é também a DT para outros acharem o transmissor. Instalar discretamente com gente presente: ação completa, Furtividade oposta à Percepção dos presentes e DT do teste de Crime +5.", "fx": [["Receptor", "Alcance de 90m"], ["Transmissores", "3, captam num raio de 9m"], ["Instalar", "Crime DT 20 (+5 se discreto, com Furtividade)"]]}'::jsonb),
('sah:item:operacional:Estrepes (saco)','op','sah','operacional','item operacional','Estrepes (saco)',1034,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 0, "esp": 1, "desc": "Peça de metal de quatro pontas afiadas, sempre com uma voltada para cima. Em combate, um saco cobre um quadrado de 1,5m com ação padrão. Quem pisa sofre 1d4 de perfuração e fica lento por um dia. Em perseguição, aplicar faz parte da sua ação, com –1d20 no seu teste naquela rodada; o perseguidor que pisa sofre –1d20 nos testes de perseguição até o fim da cena. Reflexos (DT Agi) evita. Não afeta seres que resistem a todo o dano.", "fx": [["Dano", "1d4 perfuração + lento por um dia"], ["Uso", "Ação padrão, quadrado de 1,5m"], ["Teste", "Reflexos DT Agi evita"], ["Perseguição", "–1d20 no seu teste; perseguidor –1d20 até o fim da cena"]]}'::jsonb),
('sah:item:operacional:Faixa de Pregos','op','sah','operacional','item operacional','Faixa de Pregos',1035,'{"comp": "sah", "pag": 42, "tipo": "geral", "catg": 1, "esp": 2, "desc": "Trilha de hastes metálicas sanfonadas com pregos, feita para parar veículos. Funciona como estrepes, mas ocupa uma linha de 9m. Veículos de pneus de borracha que passam pela faixa têm os pneus perfurados e o deslocamento cai pela metade.", "fx": [["Efeito", "Como estrepes, numa linha de 9m"], ["Veículos", "Pneus perfurados: deslocamento pela metade"]]}'::jsonb),
('sah:item:operacional:Isqueiro','op','sah','operacional','item operacional','Isqueiro',1036,'{"comp": "sah", "pag": 43, "tipo": "geral", "catg": 0, "esp": 0.5, "desc": "Do metal sofisticado ao descartável de plástico: ação de movimento para produzir uma chama pequena. Incendeia objetos inflamáveis e emite luz num raio de 3m.", "fx": [["Luz", "Raio de 3m"], ["Acender", "Ação de movimento"]], "luz": {"t": "l", "m": 3}}'::jsonb),
('sah:item:operacional:Óculos de Visão Noturna','op','sah','operacional','item operacional','Óculos de Visão Noturna',1037,'{"comp": "sah", "pag": 43, "tipo": "geral", "catg": 1, "esp": 1, "desc": "Funcionam a bateria e permitem enxergar no escuro, como visão no escuro. Em troca, quem usa recebe –1d20 em testes de resistência contra a condição ofuscado e contra efeitos baseados em luz (como uma granada de atordoamento).", "fx": [["Efeito", "Visão no escuro"], ["Contra", "–1d20 em resistência a ofuscado e efeitos de luz"]]}'::jsonb),
('sah:item:operacional:Óculos Escuros','op','sah','operacional','item operacional','Óculos Escuros',1038,'{"comp": "sah", "pag": 43, "tipo": "geral", "catg": 0, "esp": 1, "desc": "Quem usa óculos escuros não pode ser ofuscado.", "fx": [["Efeito", "Imune a ofuscado"]]}'::jsonb),
('sah:item:operacional:Pá','op','sah','operacional','item operacional','Pá',1039,'{"comp": "sah", "pag": 43, "tipo": "geral", "catg": 0, "esp": 2, "desc": "Ferramenta pesada: +5 em testes de Força para cavar buracos e mover detritos. Em combate vale como um bastão.", "fx": [["Bônus", "+5 em Força para cavar e mover detritos"], ["Combate", "Vale como bastão"]]}'::jsonb),
('sah:item:operacional:Paraquedas','op','sah','operacional','item operacional','Paraquedas',1040,'{"comp": "sah", "pag": 43, "tipo": "geral", "catg": 1, "esp": 2, "desc": "Anula o dano de queda. Quem tem grau veterano em Acrobacia, Pilotagem, Reflexos, Tática ou numa Profissão específica sabe usar. Os demais, ou em quedas muito curtas, precisam de Reflexos (DT 20); se falhar, o paraquedas não funciona direito e o dano de queda cai só à metade.", "fx": [["Efeito", "Anula o dano de queda"], ["Teste", "Reflexos DT 20 (dispensado para veteranos nas perícias do livro)"], ["Se falhar", "Dano de queda pela metade"]]}'::jsonb),
('sah:item:operacional:Traje de Mergulho','op','sah','operacional','item operacional','Traje de Mergulho',1041,'{"comp": "sah", "pag": 44, "tipo": "geral", "catg": 1, "esp": 2, "desc": "Roupa impermeável que cobre quase o corpo todo, com tanque e máscara para 1 hora de oxigênio. Dá +5 em testes de resistência contra efeitos ambientais e resistência a dano químico 5. Ocupa o espaço de uma vestimenta; vestir ou despir é ação completa.", "fx": [["Bônus", "+5 em resistência a efeitos ambientais"], ["Resistência", "Químico 5"], ["Oxigênio", "1 hora"], ["Vestir", "Ação completa (ocupa uma vestimenta)"]]}'::jsonb),
('sah:item:operacional:Traje Espacial','op','sah','operacional','item operacional','Traje Espacial',1042,'{"comp": "sah", "pag": 44, "tipo": "geral", "catg": 2, "esp": 5, "desc": "Roupa impermeável de corpo inteiro para o vácuo, com água e oxigênio para oito horas e proteção contra raios cósmicos e micrometeoros. Dá +10 em testes de resistência contra efeitos ambientais e resistência a dano químico 20. Ocupa o espaço de uma vestimenta; vestir ou despir leva duas rodadas.", "fx": [["Bônus", "+10 em resistência a efeitos ambientais"], ["Resistência", "Químico 20"], ["Suprimento", "8 horas de água e oxigênio"], ["Vestir", "Duas rodadas (ocupa uma vestimenta)"]]}'::jsonb),
('sah:item:medicamento:Antibiótico','op','sah','medicamento','medicamento','Antibiótico',1043,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Fortalece a imunidade contra vírus e bactérias. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Vale para o próximo teste de Fortitude contra os efeitos de uma doença feito até o fim do dia.", "fx": [["Efeito", "Fortitude +5 contra doença"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Antídoto','op','sah','medicamento','medicamento','Antídoto',1044,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Ajuda o corpo a lidar com venenos. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Vale para o próximo teste de Fortitude contra os efeitos de um veneno feito até o fim do dia. Um antídoto feito para um veneno específico, em vez disso, remove o veneno por completo.", "fx": [["Efeito", "Fortitude +5 contra veneno"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Antiemético','op','sah','medicamento','medicamento','Antiemético',1045,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Combate náuseas. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Remove a condição enjoado e dá +5 em testes para evitá-la até o fim da cena. A critério do mestre, funciona contra outras condições causadas por náuseas e vômitos.", "fx": [["Efeito", "Remove enjoado e +5 contra enjoado"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Antihistamínico','op','sah','medicamento','medicamento','Antihistamínico',1046,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Reduz reações alérgicas perigosas. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Dá +5 no próximo teste contra os efeitos de uma alergia feito até o fim do dia.", "fx": [["Efeito", "Teste contra alergia +5"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Anti-inflamatório','op','sah','medicamento','medicamento','Anti-inflamatório',1047,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Reduz inflamação, dor e inchaço. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Fornece 1d8+2 PV temporários.", "fx": [["Efeito", "Cura 1d8+2 PV temporários"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Antitérmico','op','sah','medicamento','medicamento','Antitérmico',1048,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Reduz febre e alivia dor de cabeça. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Permite um novo teste contra uma condição mental que o usuário esteja sofrendo. Só funciona uma vez por cena.", "fx": [["Efeito", "Novo teste contra condição mental"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Broncodilatador','op','sah','medicamento','medicamento','Broncodilatador',1049,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Auxilia na respiração. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Dá +5 em testes para evitar as condições asfixiado ou fatigado feitos até o fim do dia.", "fx": [["Efeito", "Contra asfixiado e fatigado +5"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:medicamento:Coagulante','op','sah','medicamento','medicamento','Coagulante',1050,'{"comp": "sah", "pag": 43, "tipo": "consumivel", "catg": 1, "esp": 0.5, "desc": "Medicamento. Aumenta a capacidade de coagulação. Ação padrão e o medicamento para aplicar em você ou em um ser adjacente. Dá +5 em testes para se estabilizar da condição sangrando feitos até o fim do dia. Usado junto com um teste de Medicina para remover a condição morrendo, também dá +5 nesse teste.", "fx": [["Efeito", "Estabilizar sangrando +5"], ["Uso", "Ação padrão (você ou ser adjacente)"]]}'::jsonb),
('sah:item:paranormal:Catalisador Ritualístico de Conhecimento (Ampliador)','op','sah','paranormal','catalisador ritualístico · Conhecimento','Catalisador Ritualístico de Conhecimento (Ampliador)',1051,'{"comp": "sah", "pag": 44, "tipo": "paranormal", "catg": 1, "esp": 0.5, "elemento": "Conhecimento", "desc": "Componente ritualístico de Conhecimento alterado por exposição paranormal, mais eficiente. É consumido ao ser usado. Você precisa empunhá-lo e só usa um catalisador por ritual; não pode ser improvisado (Improvisar Componentes), mas pode ser fabricado em campo. Serve para rituais de Conhecimento. Ampliador: Aumenta o alcance do ritual em um passo (de curto para médio, de médio para longo ou de longo para extremo) ou dobra a área de efeito. Ex.: uma Dissonância Acústica ampliada passa a alcance longo ou área de 12m de raio. Ao ser consumido, o catalisador é inexistido da Realidade. Exemplos: pergaminho com sigilos, joias paranormais, balança dourada que nunca se move, um Existido inofensivo aprisionado.", "fx": [["Elemento", "Conhecimento"], ["Efeito", "Alcance +1 passo ou área dobrada"], ["Uso", "Empunhado; consumido; 1 por ritual"]]}'::jsonb),
('sah:item:paranormal:Catalisador Ritualístico de Conhecimento (Perturbador)','op','sah','paranormal','catalisador ritualístico · Conhecimento','Catalisador Ritualístico de Conhecimento (Perturbador)',1052,'{"comp": "sah", "pag": 44, "tipo": "paranormal", "catg": 1, "esp": 0.5, "elemento": "Conhecimento", "desc": "Componente ritualístico de Conhecimento alterado por exposição paranormal, mais eficiente. É consumido ao ser usado. Você precisa empunhá-lo e só usa um catalisador por ritual; não pode ser improvisado (Improvisar Componentes), mas pode ser fabricado em campo. Serve para rituais de Conhecimento. Perturbador: A DT para resistir ao ritual aumenta em +2. Ao ser consumido, o catalisador é inexistido da Realidade. Exemplos: pergaminho com sigilos, joias paranormais, balança dourada que nunca se move, um Existido inofensivo aprisionado.", "fx": [["Elemento", "Conhecimento"], ["Efeito", "DT do ritual +2"], ["Uso", "Empunhado; consumido; 1 por ritual"]]}'::jsonb),
('sah:item:paranormal:Catalisador Ritualístico de Conhecimento (Potencializador)','op','sah','paranormal','catalisador ritualístico · Conhecimento','Catalisador Ritualístico de Conhecimento (Potencializador)',1053,'{"comp": "sah", "pag": 44, "tipo": "paranormal", "catg": 1, "esp": 0.5, "elemento": "Conhecimento", "desc": "Componente ritualístico de Conhecimento alterado por exposição paranormal, mais eficiente. É consumido ao ser usado. Você precisa empunhá-lo e só usa um catalisador por ritual; não pode ser improvisado (Improvisar Componentes), mas pode ser fabricado em campo. Serve para rituais de Conhecimento. Potencializador: O dano do ritual aumenta em um dado do mesmo tipo. Ao ser consumido, o catalisador é inexistido da Realidade. Exemplos: pergaminho com sigilos, joias paranormais, balança dourada que nunca se move, um Existido inofensivo aprisionado.", "fx": [["Elemento", "Conhecimento"], ["Efeito", "Dano +1 dado do mesmo tipo"], ["Uso", "Empunhado; consumido; 1 por ritual"]]}'::jsonb),
('sah:item:paranormal:Catalisador Ritualístico de Conhecimento (Prolongador)','op','sah','paranormal','catalisador ritualístico · Conhecimento','Catalisador Ritualístico de Conhecimento (Prolongador)',1054,'{"comp": "sah", "pag": 44, "tipo": "paranormal", "catg": 1, "esp": 0.5, "elemento": "Conhecimento", "desc": "Componente ritualístico de Conhecimento alterado por exposição paranormal, mais eficiente. É consumido ao ser usado. Você precisa empunhá-lo e só usa um catalisador por ritual; não pode ser improvisado (Improvisar Componentes), mas pode ser fabricado em campo. Serve para rituais de Conhecimento. Prolongador: A duração do ritual dobra (ex.: Distorcer Aparência prolongado dura duas cenas). Não funciona em rituais instantâneos ou sustentados. Ao ser consumido, o catalisador é inexistido da Realidade. Exemplos: pergaminho com sigilos, joias paranormais, balança dourada que nunca se move, um Existido inofensivo aprisionado.", "fx": [["Elemento", "Conhecimento"], ["Efeito", "Duração dobrada"], ["Uso", "Empunhado; consumido; 1 por ritual"]]}'::jsonb),
